CREATE TABLE `lead_management_leadfollowup` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `followup_date` date NOT NULL,
  `followup_time` time(6) DEFAULT NULL,
  `next_followup_date` date DEFAULT NULL,
  `remarks` longtext,
  `discussion_notes` longtext,
  `interaction_type` varchar(20) NOT NULL,
  `client_response` varchar(20) NOT NULL,
  `followup_status` varchar(20) NOT NULL,
  `conducted_by` varchar(200) DEFAULT NULL,
  `contacted_person` varchar(200) DEFAULT NULL,
  `followup_summary` longtext,
  `client_commitment` longtext,
  `our_commitment` longtext,
  `previous_stage` varchar(100) DEFAULT NULL,
  `current_stage` varchar(100) DEFAULT NULL,
  `status` varchar(200) NOT NULL,
  `suggested_solution` json DEFAULT NULL,
  `qualifying_info` json DEFAULT NULL,
  `requirement_info` json DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by_id` bigint DEFAULT NULL,
  `lead_id` bigint NOT NULL,
  `followup_question` longtext,
  `site_name` varchar(255) DEFAULT NULL,
  `site_photo` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `lead_management_lead_created_by_id_63cba79d_fk_api_custo` (`created_by_id`),
  KEY `lead_management_lead_lead_id_29e8202c_fk_lead_mana` (`lead_id`),
  CONSTRAINT `lead_management_lead_created_by_id_63cba79d_fk_api_custo` FOREIGN KEY (`created_by_id`) REFERENCES `api_customuser` (`id`),
  CONSTRAINT `lead_management_lead_lead_id_29e8202c_fk_lead_mana` FOREIGN KEY (`lead_id`) REFERENCES `lead_management_lead_management` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
